// Memory mapped buffers
/* cast ทิ้ง const ตรงนี้: _k3 เป็น const เพื่อให้อยู่ flash แต่ mtb_init()
 * รับพารามิเตอร์เป็น uint8_t* (ไม่ const) ตาม API เดิมของ ml-middleware */
#define _K3              ((uint8_t *)(uintptr_t)_k3)                   // u8[1682000] (1682000 bytes)
#define _K2              ((uint8_t *)(_state + 0x00000010))  // u8[891904] (891904 bytes)
#define _K6              ((int8_t *)(_state + 0x00000000))   // s8[8] (8 bytes)
#define _K1              ((int8_t *)(_buffer + 0x00000000))  // s8[320,320,3] (307200 bytes)
#define _K5              ((int8_t *)(_buffer + 0x0004b000))  // d8[6300,7] (44100 bytes)
#define _K7              ((int8_t *)(_buffer + 0x00000000))  // s8[6300,7] (44100 bytes)
#define _K8              ((int8_t *)(_buffer + 0x0000ac44))  // s8[6,5] (30 bytes)

#define IPWIN_RET_SUCCESS 0
#define IPWIN_RET_NODATA -1
#define IPWIN_RET_ERROR -2
#define IPWIN_RET_STREAMEND -3

static inline void cast_u8_to_i8(const uint8_t* restrict input, int8_t* restrict output, int32_t count)
{
    for (int i = 0; i < count; i++) {
        // Range conversion: map [0,255] to [-128,127]
        output[i] = (int8_t)((int)input[i] - 128);
    }
}

static inline int mtb_model_raw(const void* handle,
	const void* restrict src, int src_count,
	void* restrict dst, int dst_byte_count)
{
	mtb_ml_model_t* model = *(mtb_ml_model_t**)handle;
	mtb_ml_model_run(model, (MTB_ML_DATA_T*)src);
	
	int ret_status = model->lib_error;
	if (ret_status != 0) {printf("ERROR: TensorFlow Lite model inference failed with error code: %d.\r\n", ret_status);}
	CY_ASSERT(ret_status == 0);

	memcpy(dst, model->output, dst_byte_count);

	return IPWIN_RET_SUCCESS;
}

static inline void dequantize_d8_to_i8(const int8_t* restrict src, int8_t* restrict dst, int count, float scale, int offset)
{
	while (count > 0U)
	{
		int8_t raw_src = *src++;
		float val = (raw_src - offset) * scale;
		
		// Scale [0,1] range to int8 range [-128,127]
		int32_t ival = (int32_t)(val * 255.0f - 128.0f);
		if (ival > 127) ival = 127;
		else if (ival < -128) ival = -128;
		
		*dst++ = (int8_t)ival;
		
		count--;
	}
}

// Candidate detection data structure
typedef struct {
    int index;          // Original detection index
    float score;        // Confidence score
    int class_id;       // Best class index
    float box[4];       // Bounding box coordinates [x, y, w, h]
} candidate_detection_t;

// Helper function to convert int8 to float for legacy layout
static inline float get_confidence_dc_i8(const int8_t* restrict input, int confidence_count, int confidence, int detection) {
    return ((float)input[detection * confidence_count + confidence] + 128.0f) / 255.0f;
}

// Optimized for [Detection, Confidence] layout (axis_order = 1) - Int8 version
static inline void detectionfilter_legacy_i8(const int8_t* restrict input, int8_t* restrict output, int detection_count, int confidence_count, int max_detections, float threshold, float iou_threshold)
{
    // For [Detection, Confidence] layout: always format { x, y, w, h, oc, class } (with object confidence)
    int class_offset = 5;
    int num_classes = confidence_count - class_offset;
    
    // Calculate output count early to avoid redeclaration
    int output_confidence_count = confidence_count - 1;  // Remove object confidence dimension
    int output_count = output_confidence_count;

    // First pass: Find indices of detections that pass threshold (memory optimization)
    int keep_indices[detection_count];
    int num_candidates = 0;
    
    for (int i = 0; i < detection_count; ++i) {
        float max_conf = 0;

        for (int j = 0; j < num_classes; ++j) {
            float current_conf = get_confidence_dc_i8(input, confidence_count, class_offset + j, i);
            if (current_conf > max_conf) {
                max_conf = current_conf;
            }
        }

        // For [Detection, Confidence] layout: multiply object confidence with class confidence
        float obj_score = get_confidence_dc_i8(input, confidence_count, 4, i);
        float current_conf = obj_score * max_conf;

        // Keep candidates that pass threshold
        if (current_conf >= threshold) {
            keep_indices[num_candidates] = i;
            num_candidates++;
        }
    }

    // Exit if no candidates
    if (num_candidates == 0) {
        for (int i = 0; i < max_detections * output_count; ++i)
            output[i] = -128;  // Initialize with 0
        return;
    }

    // Allocate buffers sized to actual candidates (memory optimization)
    int candidate_indices[num_candidates];
    float candidate_scores[num_candidates];
    int candidate_classes[num_candidates];
    float candidate_boxes[num_candidates][4];

    // Second pass: Process only the kept indices to fill candidate buffers
    for (int idx = 0; idx < num_candidates; ++idx) {
        int i = keep_indices[idx];
        int max_class = -1;
        float max_conf = 0;

        // Find the best class for this detection
        for (int j = 0; j < num_classes; ++j) {
            float current_conf = get_confidence_dc_i8(input, confidence_count, class_offset + j, i);
            if (current_conf > max_conf) {
                max_conf = current_conf;
                max_class = j;   // Track class index
            }
        }

        candidate_indices[idx] = i;
        candidate_scores[idx] = max_conf;
        candidate_classes[idx] = max_class;

        // Extract box coordinates
        for (int j = 0; j < 4; ++j) {
            candidate_boxes[idx][j] = get_confidence_dc_i8(input, confidence_count, j, i);
        }
    }

    // Exit if no candidates
    if (num_candidates == 0) {
        for (int i = 0; i < max_detections * output_count; ++i)
            output[i] = -128;  // Initialize with 0
        return;
    }

    // Sort candidates by descending score (simple selection sort)
    for (int i = 0; i < num_candidates - 1; ++i) {
        int max_idx = i;
        for (int j = i + 1; j < num_candidates; ++j) {
            if (candidate_scores[j] > candidate_scores[max_idx])
                max_idx = j;
        }
        if (max_idx != i) {
            // Swap all candidate data
            int temp_idx = candidate_indices[i];
            candidate_indices[i] = candidate_indices[max_idx];
            candidate_indices[max_idx] = temp_idx;

            float temp_score = candidate_scores[i];
            candidate_scores[i] = candidate_scores[max_idx];
            candidate_scores[max_idx] = temp_score;

            int temp_class = candidate_classes[i];
            candidate_classes[i] = candidate_classes[max_idx];
            candidate_classes[max_idx] = temp_class;

            float temp_box[4];
            for (int k = 0; k < 4; ++k) {
                temp_box[k] = candidate_boxes[i][k];
                candidate_boxes[i][k] = candidate_boxes[max_idx][k];
                candidate_boxes[max_idx][k] = temp_box[k];
            }
        }
    }

    // Apply NMS (only compare boxes of the same class)
    int suppressed[num_candidates];
    for (int i = 0; i < num_candidates; ++i)
        suppressed[i] = 0;

    for (int i = 0; i < num_candidates - 1; ++i) {
        if (suppressed[i]) continue;

        float* box_i = candidate_boxes[i];
        int class_i = candidate_classes[i];

        for (int j = i + 1; j < num_candidates; ++j) {
            if (suppressed[j] || candidate_classes[j] != class_i) continue;

            float* box_j = candidate_boxes[j];

            // Calculate IoU between box_i and box_j
            float ix = box_i[0];  // center x
            float iy = box_i[1];  // center y
            float iw = box_i[2];  // width
            float ih = box_i[3];  // height
            float x1_i = ix - iw / 2, y1_i = iy - ih / 2;
            float x2_i = ix + iw / 2, y2_i = iy + ih / 2;

            float jx = box_j[0];  // center x
            float jy = box_j[1];  // center y
            float jw = box_j[2];  // width
            float jh = box_j[3];  // height
            float x1_j = jx - jw / 2, y1_j = jy - jh / 2;
            float x2_j = jx + jw / 2, y2_j = jy + jh / 2;

            // Calculate intersection area
            float x1 = fmaxf(x1_i, x1_j), y1 = fmaxf(y1_i, y1_j);
            float x2 = fminf(x2_i, x2_j), y2 = fminf(y2_i, y2_j);
            float inter_area = (x2 > x1 && y2 > y1) ? (x2 - x1) * (y2 - y1) : 0.0f;

            // Calculate IoU
            float area_i = iw * ih;
            float area_j = jw * jh;
            float union_area = area_i + area_j - inter_area;
            float iou = (union_area > 0) ? (inter_area / union_area) : 0.0f;

            if (iou > iou_threshold)
                suppressed[j] = 1;
        }
    }

    int output_idx = 0;
    for (int i = 0; i < num_candidates && output_idx < max_detections; ++i) {
        if (!suppressed[i]) {
            int input_idx = candidate_indices[i];
            
            // For [Detection, Confidence] layout: Format {x, y, w, h, oc, class} -> output: {x, y, w, h, multiplied_class}
            // Get object confidence for multiplication
            float obj_conf = get_confidence_dc_i8(input, confidence_count, 4, input_idx);
            
            // Copy bounding box coordinates (x, y, w, h)
            for (int j = 0; j < 4; ++j) {
                float val = get_confidence_dc_i8(input, confidence_count, j, input_idx);
                // Convert back to int8 range: [0,1] -> [-128,127]
                int8_t int8_val = (int8_t)(val * 255.0f - 128.0f);
                if (int8_val > 127) int8_val = 127;
                else if (int8_val < -128) int8_val = -128;
                output[j * max_detections + output_idx] = int8_val;
            }
            
            // Copy class confidences multiplied by object confidence (skip object confidence at index 4)
            for (int j = class_offset; j < confidence_count; ++j) {
                float class_conf = get_confidence_dc_i8(input, confidence_count, j, input_idx);
                float multiplied_conf = obj_conf * class_conf;
                // Convert back to int8 range: [0,1] -> [-128,127]
                int8_t int8_val = (int8_t)(multiplied_conf * 255.0f - 128.0f);
                if (int8_val > 127) int8_val = 127;
                else if (int8_val < -128) int8_val = -128;
                output[(j - 1) * max_detections + output_idx] = int8_val;  // j-1 to shift indices after removing oc
            }
            
            output_idx++;
        }
    }

    // Fill remaining slots with zeros
    for (; output_idx < max_detections; ++output_idx) {
        for (int j = 0; j < output_count; ++j) {
            output[j * max_detections + output_idx] = -128;  // Initialize with -128, converts to 0.0 when read
        }
    }
}

static inline void cast_i8_to_f32_range_0_1(const int8_t* restrict input, float* restrict output, int32_t count)
{
    for (int i = 0; i < count; i++) {
        // Range conversion: map [-128,127] to [0,1]
        output[i] = ((float)input[i] + 128.0f) / 255.0f;
    }
}

static inline void mtb_model_free(const void* handle)
{
	mtb_ml_model_t* model = *(mtb_ml_model_t**)handle;
	mtb_ml_model_deinit(model);

#ifndef YOLO_IMAI_NO_NPU
	mtb_ml_deinit();
#endif

	if (YOLO_IMAI_mtb_models_count > 0)
		YOLO_IMAI_mtb_models_count--;
}

#if defined(YOLO_IMAI_PROFILING_LOG)
#define MODEL_PROFILING MTB_ML_LOG_ENABLE_MODEL_LOG
#elif defined(YOLO_IMAI_PROFILING)
#define MODEL_PROFILING MTB_ML_PROFILE_ENABLE_MODEL
#endif

#define YOLO_IMAI_MAX_MTB_MODELS 4
uint8_t YOLO_IMAI_mtb_models_count = 0;
mtb_ml_model_t* YOLO_IMAI_mtb_models[YOLO_IMAI_MAX_MTB_MODELS];

void YOLO_IMAI_mtb_models_print_info() {
	if (YOLO_IMAI_mtb_models_count < 1)
		return;

	printf("Loaded %ld models:\r\n", (long int)YOLO_IMAI_mtb_models_count);
	for (uint32_t index = 0; index < YOLO_IMAI_mtb_models_count; index++) {
		printf("Model %ld:\r\n", (long int)index);
		mtb_ml_utils_print_model_info(YOLO_IMAI_mtb_models[index]);
		printf("\r\n");
	}
	printf("\r\n");
}

void YOLO_IMAI_mtb_models_profile_log() {
	if (YOLO_IMAI_mtb_models_count < 1)
		return;

	printf("Profiling %ld models:\r\n", (long int)YOLO_IMAI_mtb_models_count);
	for (uint32_t index = 0; index < YOLO_IMAI_mtb_models_count; index++) {
		printf("Model %ld: %s:\r\n", (long int)index, YOLO_IMAI_mtb_models[index]->name);
		mtb_ml_model_profile_log(YOLO_IMAI_mtb_models[index]);
		printf("\r\n");
	}
	printf("\r\n");
}

static int mtb_init(const void* handle, uint8_t* model_bin, unsigned int model_size, uint8_t* arena_buffer, int arena_size, int npu_priority, char model_name[]) {
	mtb_ml_model_t** model_obj = (mtb_ml_model_t**)handle;

	mtb_ml_model_bin_t model = {
		.model_bin = model_bin,
		.model_size = model_size,
		.arena_size = arena_size
	};

	strncpy(model.name, model_name, MTB_ML_MODEL_NAME_LEN - 1);
	model.name[MTB_ML_MODEL_NAME_LEN - 1] = '\0';

	mtb_ml_model_buffer_t buffer = {
		.tensor_arena = arena_buffer,
		.tensor_arena_size = arena_size
	};

	if (mtb_ml_model_init(&model, &buffer, model_obj) != CY_RSLT_SUCCESS)
		return IPWIN_RET_ERROR;

#ifndef YOLO_IMAI_NO_NPU
	if (mtb_ml_init(npu_priority) != CY_RSLT_SUCCESS)
		return IPWIN_RET_ERROR;
#endif

#if defined(YOLO_IMAI_PROFILING) || defined(YOLO_IMAI_PROFILING_LOG)
	if (mtb_ml_model_profile_config(*model_obj, MODEL_PROFILING) != CY_RSLT_SUCCESS)
		return IPWIN_RET_ERROR;

	YOLO_IMAI_mtb_models[YOLO_IMAI_mtb_models_count++] = *model_obj;
#endif

	return IPWIN_RET_SUCCESS;
}

#ifndef __CLOSE_HOOKS
	#define __CLOSE_HOOKS() do { } while(0)
#endif
#define __RETURN_ERROR(_exp) do { int __ret = (_exp); if(__ret < 0) { __CLOSE_HOOKS(); return __ret; } } while(0)
#define __RETURN_ALWAYS(_exp) __CLOSE_HOOKS(); return (_exp)
#define __RETURN_ERROR_BREAK_EMPTY(_exp) {  int __ret = (_exp); if(__ret == -1) break; if(__ret < 0) { __CLOSE_HOOKS(); return __ret; } }
#define __RETURN_ERROR_BREAK_EMPTY_END(_exp) {  int __ret = (_exp); if(__ret == -1 || __ret == -3) break; if(__ret < 0) { __CLOSE_HOOKS(); return __ret; } }
#define __RETURN_ERROR_CANCEL_EMPTY(_exp) {  int __ret = (_exp); if(__ret == -1) { __CLOSE_HOOKS(); return 0; } if(__ret < 0) { __CLOSE_HOOKS(); return __ret; } }
#define __BREAK_ERROR(_exp) {  int __ret = (_exp); if(__ret < 0) break; }
#define __CONTINUE_ON_EMPTY(_exp) {  int __ret = (_exp); if(__ret < -1) { __CLOSE_HOOKS(); return __ret; } }

/*
*  @param datain Input features. Input uint8_t[320,320,3].
*  @param dataout Output features. Output float[6,5].
*  @return IPWIN_RET_SUCCESS (0) or IPWIN_RET_NODATA (-1), IPWIN_RET_ERROR (-2), IPWIN_RET_STREAMEND (-3)
*/
int YOLO_IMAI_compute(const uint8_t *restrict datain, float *restrict dataout) {    
    cast_u8_to_i8(datain, _K1, 307200);
    __RETURN_ERROR(mtb_model_raw(_K6, _K1, 307200, _K5, 44100));
    dequantize_d8_to_i8(_K5, _K7, 44100, 0.00631333515048027, -128);
    detectionfilter_legacy_i8(_K7, _K8, 6300, 7, 5, 0.5, 0.5);
    cast_i8_to_f32_range_0_1(_K8, dataout, 30);
    return 0;
}

/*
* Closes and flushes streams, free any heap allocated memory.
* 
*/
void YOLO_IMAI_finalize(void) {    
    mtb_model_free(_K6);
}

/*
* Initializes buffers to initial state.
* 
*  @return IPWIN_RET_SUCCESS (0) or IPWIN_RET_NODATA (-1), IPWIN_RET_ERROR (-2), IPWIN_RET_STREAMEND (-3)
*/
int YOLO_IMAI_init(void) {    
    __RETURN_ERROR(mtb_init(_K6, _K3, 1682000, _K2, 891904, 3, "yolov5n-legacy-size320-batch16-epoch500_int8.imunit TFLite Model_int8x8"));
    return 0;
}

